import { useState } from 'react';

function AuthDialog({ onClose, onSubmit }) {
  const [isRegistering, setIsRegistering] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');

  async function handleSubmit(event) {
    event.preventDefault();
    setError('');
    setIsSubmitting(true);
    const form = new FormData(event.currentTarget);
    const credentials = {
      email: String(form.get('email') || '').trim(),
      password: String(form.get('password') || ''),
    };
    if (isRegistering) credentials.displayName = String(form.get('displayName') || '').trim();

    try {
      await onSubmit(credentials, isRegistering);
    } catch (submitError) {
      setError(submitError.message || 'Authentication failed. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <div className="auth-backdrop" onMouseDown={(event) => {
      if (event.target === event.currentTarget) onClose();
    }}>
      <form className="auth-dialog" onSubmit={handleSubmit} aria-labelledby="auth-title">
        <button className="dialog-close" type="button" onClick={onClose} aria-label="Close sign in">×</button>
        <h2 id="auth-title">{isRegistering ? 'Create account' : 'Sign in'}</h2>
        <p>{isRegistering ? 'Save your completed games to your account.' : 'Sign in to view and save your games.'}</p>
        {isRegistering && (
          <label>
            Display name
            <input name="displayName" type="text" autoComplete="name" minLength="2" maxLength="60" required />
          </label>
        )}
        <label>
          Email
          <input name="email" type="email" autoComplete="email" maxLength="254" required />
        </label>
        <label>
          Password
          <input name="password" type="password" autoComplete={isRegistering ? 'new-password' : 'current-password'} minLength="8" required />
        </label>
        {error && <p className="form-error" role="alert">{error}</p>}
        <button className="auth-submit" type="submit" disabled={isSubmitting}>
          {isSubmitting ? 'Please wait…' : isRegistering ? 'Create account' : 'Sign in'}
        </button>
        <button className="auth-switch" type="button" onClick={() => {
          setIsRegistering((current) => !current);
          setError('');
        }}>
          {isRegistering ? 'Already have an account? Sign in' : 'Need an account? Create one'}
        </button>
      </form>
    </div>
  );
}

export default AuthDialog;
